H=Path('app/src/main/assets/index.html'); J=Path('app/src/main/assets/social.js'); C=Path('app/src/main/assets/social.css'); A=Path('app/src/main/java/com/hsnsn/actiontemplate/MainActivity.java')
h=H.read_text(); j=J.read_text(); c=C.read_text(); a=A.read_text()

