# Search must report the real friendship/pending state.
old='''        private void sendSearchDoc(FirebaseUser me,DocumentSnapshot d){try{JSONObject out=new JSONObject();out.put("ok",true);out.put("action","search");JSONObject p=new JSONObject();p.put("uid",d.getId());p.put("name",str(d,"name","محقق"));p.put("username",str(d,"username",""));p.put("rank",str(d,"rank","صانع الدور"));p.put("self",d.getId().equals(me.getUid()));out.put("player",p);sendSocial(out);}catch(Exception e){socialError("search",e);}}
        private void sendSearchResult(FirebaseUser me,QuerySnapshot snap){try{JSONObject out=new JSONObject();out.put("ok",true);out.put("action","search");for(DocumentSnapshot d:snap.getDocuments()){JSONObject p=new JSONObject();p.put("uid",d.getId());p.put("name",str(d,"name","محقق"));p.put("username",str(d,"username",""));p.put("rank",str(d,"rank","صانع الدور"));p.put("self",d.getId().equals(me.getUid()));out.put("player",p);break;}sendSocial(out);}catch(Exception e){socialError("search",e);}}
'''
new='''        private JSONObject roleplayPlayer(DocumentSnapshot d)throws Exception{JSONObject p=new JSONObject();p.put("uid",d.getId());p.put("name",str(d,"name","لاعب"));p.put("username",str(d,"username",""));p.put("rank",str(d,"rank","صانع الدور"));p.put("level",number(d,"level",1));p.put("cases",number(d,"cases",0));p.put("solved",number(d,"solved",0));p.put("accuracy",number(d,"accuracy",0));p.put("xpPercent",number(d,"xpPercent",8));p.put("equipped",str(d,"equippedCosmetics","{}"));return p;}
        private void sendSearchDoc(FirebaseUser me,DocumentSnapshot d){Task<DocumentSnapshot> f=firestore.collection("users").document(me.getUid()).collection("friends").document(d.getId()).get();Task<DocumentSnapshot> r=firestore.collection("friendRequests").document(requestId(me.getUid(),d.getId())).get();Tasks.whenAllSuccess(f,r).addOnSuccessListener(x->{try{JSONObject out=new JSONObject();out.put("ok",true);out.put("action","search");JSONObject p=roleplayPlayer(d);p.put("self",d.getId().equals(me.getUid()));p.put("friend",((DocumentSnapshot)x.get(0)).exists());DocumentSnapshot q=(DocumentSnapshot)x.get(1);p.put("requested",q.exists()&&"pending".equals(str(q,"status","")));out.put("player",p);sendSocial(out);}catch(Exception e){socialError("search",e);}});}
        private void sendSearchResult(FirebaseUser me,QuerySnapshot snap){if(!snap.isEmpty())sendSearchDoc(me,snap.getDocuments().get(0));else try{JSONObject o=new JSONObject();o.put("ok",true);o.put("action","search");sendSocial(o);}catch(Exception ignored){}}
'''
if old not in a: raise SystemExit('search helpers changed; refusing unsafe patch')
a=a.replace(old,new,1)

# Public identity card data + account-backed cosmetics.
mark='        @JavascriptInterface public void searchPlayer(String query) {'
methods='''        @JavascriptInterface public void loadPublicProfile(String uid){runOnUiThread(()->{FirebaseUser me=currentUser();if(me==null)return;ensureFirestore();firestore.collection("users").document(uid).get().addOnSuccessListener(d->{try{JSONObject o=new JSONObject();o.put("ok",true);o.put("action","publicProfile");o.put("player",roleplayPlayer(d));sendSocial(o);}catch(Exception e){socialError("publicProfile",e);}});});}\n        @JavascriptInterface public void saveCosmetics(String inventory,String equipped){runOnUiThread(()->{FirebaseUser me=currentUser();if(me==null)return;ensureFirestore();Map<String,Object> m=new HashMap<>();m.put("inventoryCosmetics",inventory);m.put("equippedCosmetics",equipped);firestore.collection("users").document(me.getUid()).set(m,com.google.firebase.firestore.SetOptions.merge());});}\n        @JavascriptInterface public void loadCosmetics(){runOnUiThread(()->{FirebaseUser me=currentUser();if(me==null)return;ensureFirestore();firestore.collection("users").document(me.getUid()).get().addOnSuccessListener(d->{try{JSONObject o=new JSONObject();o.put("ok",true);o.put("action","cosmetics");o.put("inventory",str(d,"inventoryCosmetics",""));o.put("equipped",str(d,"equippedCosmetics",""));sendSocial(o);}catch(Exception ignored){}});});}\n\n'''
if 'loadPublicProfile(String uid)' not in a:a=a.replace(mark,methods+mark,1)

# Correct search button state and attach uid to player cards.
old_status='const status=p.self?\'<button class="tiny-btn" disabled>هذا حسابك</button>\':(p.requested?\'<button class="tiny-btn" disabled>تم إرسال الطلب</button>\':`<button class="tiny-btn primary-mini" data-add="${esc(p.uid)}">إضافة صديق</button>`);'
new_status='const status=p.self?\'<button class="tiny-btn" disabled>هذا حسابك</button>\':(p.friend?`<button class="tiny-btn" data-chat="${esc(p.uid)}" data-name="${esc(p.name)}">مراسلة</button>`:(p.requested?\'<button class="tiny-btn" disabled>تم إرسال الطلب</button>\':`<button class="tiny-btn primary-mini" data-add="${esc(p.uid)}">إضافة صديق</button>`));'
if old_status in j:j=j.replace(old_status,new_status,1)
j=j.replace('return `<div class="person-card">','return `<div class="person-card" data-uid="${esc(p.uid)}">',1)
j=j.replace('<div class="request-card"><div class="mini-avatar">','<div class="request-card" data-uid="${esc(p.uid)}"><div class="mini-avatar">',1)

# Inventory entry and the public card (only the top identity card, never owner controls/badges).
if 'id="inventoryBtn"' not in h:h=h.replace('<div class="section-title"><h3>الحساب</h3>','<div class="section-title"><h3>المظهر والمخزون</h3><small>عناصرك المملوكة</small></div><button id="inventoryBtn" class="setting-action">المخزون</button><div class="section-title"><h3>الحساب</h3>',1)
if 'id="publicIdentityCard"' not in h:h=h.replace('<script src="app.js"></script>','''<main id="inventoryView" class="cosmetic-view" hidden><header><button id="inventoryBack">‹</button><h2>المخزون</h2></header><div id="inventoryGrid" class="cosmetic-grid"></div></main><div id="publicIdentityCard" class="public-identity-overlay" hidden><div class="public-identity-card"><button id="publicIdentityClose">×</button><div id="publicIdentityAvatar" class="public-avatar-core">ل</div><h2 id="publicIdentityName">اللاعب</h2><p id="publicIdentityUsername">@username</p><p id="publicIdentityRank">صانع الدور</p><div>المستوى <b id="publicIdentityLevel">1</b></div><div class="xp"><i id="publicIdentityXp"></i></div><div class="public-stats"><span><b id="publicIdentityRoles">0</b><small>الأدوار</small></span><span><b id="publicIdentityDone">0</b><small>المكتملة</small></span><span><b id="publicIdentityAchievement">0%</b><small>الإنجاز</small></span></div></div></div><script src="app.js"></script>''',1)
