h=re.sub(r'<div class="store-grid">.*?</div></div></main>', '<div id="cosmeticStoreGrid" class="cosmetic-grid"></div></div></main>',h,count=1,flags=re.S)

if '/* roleplay-batch-one */' not in c:c+='''\n/* roleplay-batch-one */\n.cosmetic-view{position:fixed;inset:0;z-index:190;background:#050708;color:#fff;padding:24px;overflow:auto}.cosmetic-view[hidden],.public-identity-overlay[hidden]{display:none!important}.cosmetic-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.cosmetic-item{padding:14px;border:1px solid #30383e;border-radius:18px;background:#0d1215;text-align:center}.cosmetic-preview,.public-avatar-core{width:76px;height:76px;border-radius:50%;display:grid;place-items:center;margin:0 auto 10px;background:#171d21;font-size:28px;font-weight:900}.frame-fire{box-shadow:0 0 0 4px #8f3a28}.frame-silver{box-shadow:0 0 0 4px #aeb8c0}.frame-gold{box-shadow:0 0 0 4px #8c762d}.frame-night{box-shadow:0 0 0 4px #4b5578}.cosmetic-item button{width:100%;min-height:40px;background:#151b1f;color:#fff;border:1px solid #ffffff24;border-radius:12px}.public-identity-overlay{position:fixed;inset:0;z-index:230;background:#000d;display:grid;place-items:center;padding:20px}.public-identity-card{width:min(100%,520px);background:#090d10;border:1px solid #30383e;border-radius:28px;padding:28px;text-align:center}.public-identity-card>button{float:left;border-radius:50%;background:#151b1f;color:#fff;border:1px solid #ffffff24}.public-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:15px}.public-stats span{padding:10px;border:1px solid #293137;border-radius:12px}.public-stats b,.public-stats small{display:block}.public-identity-card .xp{height:7px;background:#222a2f;margin:8px}.public-identity-card .xp i{display:block;height:100%;background:#8d2931}\n'''

runtime=r'''
;(()=>{const BATCH_ONE=true,$=id=>document.getElementById(id),ADMIN='bajanznsb@gmail.com';window.FIRST_ROLEPLAY_PUBLIC_CARD=true;const F=[['f1','جمر','frame-fire'],['f2','فضة','frame-silver'],['f3','ملكي','frame-gold'],['f4','ليل','frame-night']],V=[['a1','رعد','ر'],['a2','نادر','ن'],['a3','ساهر','س'],['a4','مزن','م']];const admin=()=>((localStorage.getItem('auth_email')||localStorage.getItem('investigator_email')||'').toLowerCase()===ADMIN),inv=()=>{try{return JSON.parse(localStorage.getItem('rp_inv')||'{"frames":[],"avatars":[]}')}catch{return{frames:[],avatars:[]}}},eq=()=>{try{return JSON.parse(localStorage.getItem('rp_eq')||'{}')}catch{return{}}};function sync(){try{NativeSocial?.saveCosmetics?.(JSON.stringify(inv()),JSON.stringify(eq()))}catch{}}function use(k,id){let x=inv();if(!admin()&&!x[k+'s'].includes(id))x[k+'s'].push(id);localStorage.setItem('rp_inv',JSON.stringify(x));let e=eq();e[k]=id;localStorage.setItem('rp_eq',JSON.stringify(e));sync();render()}function card(k,x){let own=admin()||inv()[k+'s'].includes(x[0]),on=eq()[k]===x[0],p=k==='frame'?`<div class="cosmetic-preview ${x[2]}">ل</div>`:`<div class="cosmetic-preview">${x[2]}</div>`;return `<div class="cosmetic-item">${p}<b>${k==='frame'?'إطار ': 'أفاتار '}${x[1]}</b><small>مجاني</small><button data-kind="${k}" data-item="${x[0]}">${on?'مستخدم':own?'استخدام':'أخذ مجانًا'}</button></div>`}function render(){let all=[...F.map(x=>card('frame',x)),...V.map(x=>card('avatar',x))].join('');if($('cosmeticStoreGrid'))$('cosmeticStoreGrid').innerHTML=all;if($('inventoryGrid'))$('inventoryGrid').innerHTML=all}document.addEventListener('click',e=>{let b=e.target.closest?.('[data-item]');if(b)use(b.dataset.kind,b.dataset.item)});$('inventoryBtn')?.addEventListener('click',()=>{document.querySelectorAll('main').forEach(x=>x.hidden=true);$('inventoryView').hidden=false;render()});$('inventoryBack')?.addEventListener('click',()=>window.openInvestigatorProfile?.());$('storeTab')?.addEventListener('click',()=>setTimeout(render,0));$('publicIdentityClose')?.addEventListener('click',()=>$('publicIdentityCard').hidden=true);document.getElementById('social')?.addEventListener('click',e=>{let q=e.target.closest('.person-card,.request-card');if(!q||e.target.closest('button'))return;e.stopImmediatePropagation();if(q.dataset.uid)NativeSocial?.loadPublicProfile?.(q.dataset.uid)},true);const old=window.onNativeSocialResult;window.onNativeSocialResult=r=>{if(r?.action==='publicProfile'&&r.ok){let p=r.player||{};$('publicIdentityName').textContent=p.name||'لاعب';$('publicIdentityUsername').textContent=p.username?'@'+p.username:'@—';$('publicIdentityRank').textContent=p.rank||'صانع الدور';$('publicIdentityLevel').textContent=p.level||1;$('publicIdentityRoles').textContent=p.cases||0;$('publicIdentityDone').textContent=p.solved||0;$('publicIdentityAchievement').textContent=(p.accuracy||0)+'%';$('publicIdentityXp').style.width=(p.xpPercent||8)+'%';$('publicIdentityAvatar').textContent=(p.name||'ل')[0];$('publicIdentityCard').hidden=false;return}if(r?.action==='cosmetics'&&r.ok){try{if(r.inventory){localStorage.setItem('rp_inv',r.inventory)}if(r.equipped)localStorage.setItem('rp_eq',r.equipped)}catch{}render();return}old?.(r)};setTimeout(()=>{render();NativeSocial?.loadCosmetics?.()},250)})();
'''
if 'const BATCH_ONE=true' not in j:j+=runtime
# Disable the old little badge/modal player profile.
j=j.replace("if(!card||e.target.closest('button'))return;const name=card.querySelector", "if(!card||e.target.closest('button')||window.FIRST_ROLEPLAY_PUBLIC_CARD)return;const name=card.querySelector")

